package org.libreshelf
import android.app.*
import android.appwidget.AppWidgetManager
import android.content.*
import android.net.Uri
import android.os.*
import android.graphics.Color
import android.widget.*
import android.view.*
import java.util.concurrent.Executors

class MainActivity:Activity(){
 private lateinit var lib:Library;private lateinit var root:LinearLayout;private val worker=Executors.newSingleThreadExecutor();private var busy=false;private var search=""
 override fun onCreate(s:Bundle?){super.onCreate(s);lib=Library(this);show()}
 private fun dp(n:Int)=(n*resources.displayMetrics.density).toInt()
 private fun text(t:String,size:Float=16f)=TextView(this).apply{text=t;textSize=size;setTextColor(0xff263b35.toInt());setPadding(0,dp(7),0,dp(7))}
 private fun button(t:String,action:()->Unit){root.addView(Button(this).apply{text=t;isAllCaps=false;isEnabled=!busy;setOnClickListener{action()}})}
 private fun show(){val scroll=ScrollView(this).apply{isFillViewport=true;setBackgroundColor(0xfff5f1e9.toInt())};root=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(20),dp(42),dp(20),dp(36))};scroll.addView(root);setContentView(scroll);root.addView(text("LibreShelf",32f));root.addView(text(if(busy)"Indexing books…" else "Your books. Your reader. Your shelf."));button("Add book folder"){startActivityForResult(Intent(Intent.ACTION_OPEN_DOCUMENT_TREE).addFlags(65),1)};button("Pin individual books"){startActivityForResult(Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true).addFlags(65),2)};button("Refresh folders"){work{val current=lib.books().toMutableList();for(f in lib.folders()){val found=lib.scan(Uri.parse(f));val pins=current.filter{it.pinned}.map{it.uri}.toSet();current.removeAll{it.folder==f&&!it.pinned};for(b in found){val old=current.find{it.uri==b.uri};current.removeAll{it.uri==b.uri};current.add(b.copy(pinned=b.uri in pins,folder=old?.folder?.ifBlank{f}?:f))}};lib.save(current)}};button("Shelf appearance & mode"){appearance()};button("Default reader"){reader("reader",null)};button("Add widget to home screen"){val m=AppWidgetManager.getInstance(this);if(m.isRequestPinAppWidgetSupported)m.requestPinAppWidget(ComponentName(this,ShelfWidget::class.java),null,null)else Toast.makeText(this,"Add LibreShelf from your launcher's widget picker",Toast.LENGTH_LONG).show()};val all=lib.books();root.addView(text("Library · ${all.size} books",22f));val input=EditText(this).apply{hint="Search titles and authors";setSingleLine();setText(search)};root.addView(input);val list=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL};root.addView(list);fun fill(){list.removeAllViews();all.filter{it.title.contains(search,true)||it.author.contains(search,true)}.sortedWith(compareByDescending<Book>{it.pinned}.thenBy{it.title.lowercase()}).take(500).forEach{b->val row=LinearLayout(this).apply{gravity=Gravity.CENTER_VERTICAL};val iv=ImageView(this).apply{setImageBitmap(Art.book(lib,b,76,104));contentDescription=b.title};row.addView(iv,LinearLayout.LayoutParams(dp(54),dp(74)));val t=text((if(b.pinned)"★ " else "")+b.title+"\n"+listOf(b.author,b.format.uppercase()).filter{it.isNotBlank()}.joinToString(" · "),15f);row.addView(t,LinearLayout.LayoutParams(0,-2,1f));row.setOnClickListener{bookMenu(b)};list.addView(row)}};fill();input.addTextChangedListener(object:android.text.TextWatcher{override fun beforeTextChanged(s:CharSequence?,a:Int,c:Int,f:Int){};override fun onTextChanged(s:CharSequence?,a:Int,b:Int,c:Int){search=s.toString();fill()};override fun afterTextChanged(s:android.text.Editable?){} })}
 private fun work(action:()->Unit){if(busy)return;busy=true;show();worker.execute{val result=runCatching{action()};runOnUiThread{busy=false;if(!isDestroyed){show();ShelfWidget.refresh(this);result.exceptionOrNull()?.let{Toast.makeText(this,it.message?:"Could not index books",Toast.LENGTH_LONG).show()}}}}}
 override fun onActivityResult(r:Int,c:Int,d:Intent?){super.onActivityResult(r,c,d);if(c!=RESULT_OK||d==null)return;val uris=mutableListOf<Uri>();d.data?.let{uris.add(it)};d.clipData?.let{for(i in 0 until it.itemCount)uris.add(it.getItemAt(i).uri)};val granted=uris.distinct().filter{u->runCatching{contentResolver.takePersistableUriPermission(u,Intent.FLAG_GRANT_READ_URI_PERMISSION)}.isSuccess};if(granted.isEmpty()){Toast.makeText(this,"Persistent access was not granted",Toast.LENGTH_LONG).show();return};work{val all=lib.books().toMutableList();for(u in granted){if(r==1){val found=lib.scan(u);lib.addFolder(u.toString());for(b in found){val old=all.find{it.uri==b.uri};all.removeAll{it.uri==b.uri};all.add(b.copy(pinned=old?.pinned?:false))}}else{val b=lib.parse(u,lib.name(u),true);val old=all.find{it.uri==b.uri};all.removeAll{it.uri==b.uri};all.add(b.copy(folder=old?.folder.orEmpty()))}};lib.save(all)}}
 private fun bookMenu(b:Book){val actions=arrayOf("Open book",if(b.pinned)"Unpin" else "Pin permanently","Choose reader for this book","Choose reader for ${b.format.uppercase()}","Remove from index");AlertDialog.Builder(this).setTitle(b.title).setItems(actions){_,i->when(i){0->startActivity(Intent(this,OpenBook::class.java).setData(Uri.parse(b.uri)));1->{lib.save(lib.books().map{if(it.uri==b.uri)it.copy(pinned=!it.pinned)else it});show();ShelfWidget.refresh(this)};2->reader("reader:${b.uri}",b.format);3->reader("reader:${b.format}",b.format);4->{lib.save(lib.books().filter{it.uri!=b.uri});show();ShelfWidget.refresh(this)}}}.show()}
 private fun reader(key:String,format:String?){val formats=if(format==null)listOf("application/pdf","application/epub+zip","application/vnd.comicbook+zip","application/x-cbz")else when(format){"pdf"->listOf("application/pdf");"epub"->listOf("application/epub+zip");else->listOf("application/vnd.comicbook+zip","application/x-cbz")};val apps=formats.flatMap{packageManager.queryIntentActivities(Intent(Intent.ACTION_VIEW).setDataAndType(Uri.parse("content://org.libreshelf/example"),it),android.content.pm.PackageManager.MATCH_DEFAULT_ONLY)}.distinctBy{it.activityInfo.packageName};val names=listOf("Ask every time / inherit")+apps.map{it.loadLabel(packageManager).toString()};AlertDialog.Builder(this).setTitle("Preferred reader").setItems(names.toTypedArray()){_,i->val e=lib.p.edit();if(i==0)e.remove(key)else e.putString(key,apps[i-1].activityInfo.packageName);e.apply()}.show()}
 private fun appearance(){
  val v=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(20),0,dp(20),0)}
  val draft=Library(this,"appearance_preview");draft.p.edit().clear().apply()
  val keys=mutableSetOf<String>();val preview=ImageView(this).apply{scaleType=ImageView.ScaleType.FIT_CENTER;setBackgroundColor(0xffb4aea0.toInt());contentDescription="Live shelf appearance preview"};v.addView(text("Live preview"));v.addView(preview,LinearLayout.LayoutParams(-1,dp(145)))
  val samples=lib.visible().take(4).ifEmpty{listOf(Book("preview:1","Process and Reality","Whitehead","epub"),Book("preview:2","The Republic","Plato","pdf"),Book("preview:3","The Trial","Kafka","epub"))}
  fun redraw(){val out=android.graphics.Bitmap.createBitmap(400,155,android.graphics.Bitmap.Config.ARGB_8888);val canvas=android.graphics.Canvas(out);val paint=android.graphics.Paint(3);val n=draft.p.getInt("count",5);val w=(380/n).coerceAtMost(100);val h=(w*1.25).toInt().coerceAtMost(130);val shown=samples.take(n);shown.forEachIndexed{i,b->val art=Art.book(draft,b,w,h);canvas.drawBitmap(art,(400-shown.size*w)/2f+i*w,133f-h,paint);art.recycle()};val plank=Art.plank(draft);canvas.drawBitmap(plank,null,android.graphics.RectF(5f,133f,395f,153f),paint);plank.recycle();preview.setImageBitmap(out)}
  fun choice(label:String,key:String,values:List<String>,default:String){keys.add(key);val value=lib.p.getString(key,default)?:default;draft.p.edit().putString(key,value).apply();v.addView(text(label));val sp=Spinner(this);sp.adapter=ArrayAdapter(this,android.R.layout.simple_spinner_dropdown_item,values);sp.setSelection(values.indexOf(value).coerceAtLeast(0));v.addView(sp);sp.onItemSelectedListener=object:AdapterView.OnItemSelectedListener{override fun onNothingSelected(p:AdapterView<*>?){};override fun onItemSelected(p:AdapterView<*>?,view:View?,pos:Int,id:Long){draft.p.edit().putString(key,values[pos]).apply();redraw()}}}
  fun slider(label:String,key:String,max:Int,default:Int,min:Int=0){keys.add(key);val value=lib.p.getInt(key,default).coerceIn(min,max);draft.p.edit().putInt(key,value).apply();val t=text("$label: $value");v.addView(t);v.addView(SeekBar(this).apply{this.max=max-min;progress=value-min;setOnSeekBarChangeListener(object:SeekBar.OnSeekBarChangeListener{override fun onStartTrackingTouch(s:SeekBar?){};override fun onStopTrackingTouch(s:SeekBar?){};override fun onProgressChanged(s:SeekBar?,p:Int,u:Boolean){t.text="$label: ${p+min}";draft.p.edit().putInt(key,p+min).apply();redraw()}})})}
  choice("Shelf mode","mode",listOf("Hybrid","Permanent","Dynamic"),"Hybrid");choice("Material","theme",listOf("Oak","Walnut","Mahogany","Birch","Graphite","Glass","Invisible"),"Oak");slider("Books per row","count",8,5,2);slider("Shadow","shadow",100,65);slider("Shadow softness","softness",100,50);slider("Wood grain","grain",100,65);slider("Lighting","light",100,75);slider("Binding","spine",100,55);slider("Corner radius","radius",6,2);choice("Auto rotation (minutes)","rotation",listOf("Off","15","30","60","120"),"Off");choice("Rotation behavior","pinRotation",listOf("Rotate all","Keep pins visible"),"Rotate all");redraw()
  AlertDialog.Builder(this).setTitle("Appearance").setView(ScrollView(this).apply{addView(v)}).setPositiveButton("Apply"){_,_->val e=lib.p.edit();for(key in keys){when(val value=draft.p.all[key]){is String->e.putString(key,value);is Int->e.putInt(key,value)}};e.apply();ShelfWidget.refresh(this)}.setNegativeButton("Cancel",null).show()
 }
}
